package com.android.tools.lint.checks;

import static com.android.SdkConstants.ANDROID_URI;
import static com.android.SdkConstants.ATTR_NAME;
import static com.android.SdkConstants.TAG_ACTION;

import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.JavaContext;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import com.google.common.collect.Lists;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import org.jetbrains.uast.UMethod;
import org.w3c.dom.Element;

public class AndroidAutoDetector extends Detector implements XmlScanner, SourceCodeScanner {

    private static final String ACTION_MEDIA_PLAY_FROM_SEARCH =
            "android.media.action.MEDIA_PLAY_FROM_SEARCH";

    public static final Issue MISSING_ON_PLAY_FROM_SEARCH = Issue.create(
            "MissingOnPlayFromSearch",
            "Missing onPlayFromSearch implementation",
            "To support voice searches on Android Auto, you must implement "
                    + "`onPlayFromSearch(String query, Bundle bundle)` in your "
                    + "`MediaSession.Callback` (or media browser service callback) when you "
                    + "declare the `MEDIA_PLAY_FROM_SEARCH` intent filter. See "
                    + "https://developer.android.com/training/auto/audio/index.html#support_voice",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            new Implementation(AndroidAutoDetector.class,
                    EnumSet.of(Scope.MANIFEST_SCOPE, Scope.JAVA_FILE_SCOPE))
    );

    private boolean mHasPlayFromSearchIntent;
    private Location mIntentLocation;
    private boolean mHasOnPlayFromSearchOverride;

    @Override
    public void beforeCheckRootProject(@NonNull Context context) {
        mHasPlayFromSearchIntent = false;
        mIntentLocation = null;
        mHasOnPlayFromSearchOverride = false;
    }

    @Override
    public List<String> getApplicableElements() {
        return Collections.singletonList(TAG_ACTION);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String name = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
        if (ACTION_MEDIA_PLAY_FROM_SEARCH.equals(name)) {
            mHasPlayFromSearchIntent = true;
            if (mIntentLocation == null) {
                mIntentLocation = context.getLocation(element);
            }
        }
    }

    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        List<Class<? extends UElement>> types = new ArrayList<>();
        types.add(UMethod.class);
        return types;
    }

    @Override
    public UElementHandler createUastHandler(@NonNull JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitMethod(@NonNull UMethod method) {
                if ("onPlayFromSearch".equals(method.getName())
                        && hasStringAndBundleParameters(method)) {
                    mHasOnPlayFromSearchOverride = true;
                }
            }
        };
    }

    private static boolean hasStringAndBundleParameters(@NonNull UMethod method) {
        PsiParameterList parameterList = method.getParameterList();
        if (parameterList.getParametersCount() != 2) {
            return false;
        }
        PsiParameter[] parameters = parameterList.getParameters();
        return "java.lang.String".equals(parameters[0].getType().getCanonicalText())
                && "android.os.Bundle".equals(parameters[1].getType().getCanonicalText());
    }

    @Override
    public void afterCheckRootProject(@NonNull Context context) {
        if (mHasPlayFromSearchIntent && !mHasOnPlayFromSearchOverride) {
            context.report(MISSING_ON_PLAY_FROM_SEARCH, mIntentLocation != null
                            ? mIntentLocation : Location.create(context.file),
                    "You must override onPlayFromSearch(String, Bundle) to support voice searches on Android Auto");
        }
    }
}

